def acled_agg_block(grid, admin, origin):
    """The 114 columns of each row at its ACLED cutoff A = O - 1 (NaN outside the grid) and the cutoff months."""
    cp, _, _ = ae_modules()
    cutoff = np.asarray(origin, dtype=np.int64) - ACLED_AGG_LAG
